// The old curated list, kept for ranking: someone typing "del" wants Delhi
// above Deline, and there are 7,519 candidates now.
const POPULAR = new Set(["DEL","ATQ","IXC","IXJ","SXR","IXL","DED","LKO","VNS","KNU","AGR","IXD","GOP","JAI","JDH","UDR","BKB","BOM","PNQ","AMD","STV","BDQ","BHJ","PBD","NAG","ISK","IXU","GOI","GOX","BLR","MAA","HYD","COK","TRV","CCJ","IXE","CJB","IXM","TRZ","TIR","VGA","VTZ","HBX","MYQ","CCU","BBI","IXR","PAT","GAY","RPR","BHO","IDR","GWL","JLR","GAU","DIB","JRH","IXS","IXA","IMF","AJL","SHL","DMU","IXB","IXZ","DXB","AUH","SHJ","DOH","SIN","KUL","BKK","DMK","HKG","CMB","KTM","DAC","LHR","JFK"]);

export const AIRPORT_OPTIONS = ENTRIES.map(([code, city, countryIndex, name]) => ({
  code,
  city,
  country: COUNTRIES[countryIndex],
  name: name || '',
}));

const BY_CODE = new Map(AIRPORT_OPTIONS.map((a) => [a.code, a]));

export const findAirportByCode = (code) =>
  BY_CODE.get(String(code || '').trim().toUpperCase()) || null;

// Ranked, because with 7,519 candidates an unranked "del" returns whichever
// matches came first rather than Delhi. Order follows TripJack's own
// autocomplete: the code, then the city, then the airport's name - which is
// why searching "del" there also surfaces Del Bajio in Mexico.
export const searchAirports = (query, limit = 8) => {
  const q = String(query || '').trim().toUpperCase();
  if (q.length < 2) return [];

  const scored = [];
  for (const airport of AIRPORT_OPTIONS) {
    const city = airport.city.toUpperCase();
    const name = airport.name.toUpperCase();
    let score = null;
    if (airport.code === q) score = 0;
    else if (city === q) score = 1;
    else if (city.startsWith(q)) score = 2;
    else if (airport.code.startsWith(q)) score = 3;
    else if (city.includes(q)) score = 4;
    else if (name.startsWith(q)) score = 5;
    else if (name.includes(q)) score = 6;
    else if (airport.country.toUpperCase().startsWith(q)) score = 7;
    if (score === null) continue;
    scored.push([score - (POPULAR.has(airport.code) ? 0.5 : 0), airport]);
    if (scored.length > 400) break;
  }

  return scored
    .sort((a, b) => a[0] - b[0])
    .slice(0, limit)
    .map(([, airport]) => airport);
};
